const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || !rows[0].payload) {
  node.error('SCAE não retornou o payload de usuários.', msg);
  return null;
}
msg.payload = rows[0].payload;
const key = env.get('HIDROCONDO_SCAE_SYNC_KEY');
if (!key) {
  node.error('Defina HIDROCONDO_SCAE_SYNC_KEY no ambiente do Node-RED.', msg);
  return null;
}
msg.headers = {'Content-Type':'application/json','x-scae-key':key};
msg.method='POST';
msg.url='https://hidrocondo.tecmen.com.br/api/v1/scae/usuarios/sync';
return msg;

